import heapq

def solve(nums, k):
    def count_less_equal(x):
        count = 0
        for num in nums:
            if num <= x:
                count += 1
        return count

    left, right = min(nums), max(nums)
    while left < right:
        mid = (left + right) // 2
        if count_less_equal(mid) >= k:
            right = mid
        else:
            left = mid + 1
    return left
