import heapq

def solve(nums, k):
    def kth_smallest(heap, k):
        while k > 1:
            heapq.heappop(heap)
            k -= 1
        return heap[0]

    heap = nums.copy()
    heapq.heapify(heap)
    return kth_smallest(heap, k)
