def solve(nums, k):
    def custom_heapify(heap, element, k):
        heapq.heappush(heap, (element, element))
        if len(heap) > k:
            heapq.heappop(heap)

    heap = []
    for num in nums:
        custom_heapify(heap, num, k)

    return heap[0][0]
