import heapq

def solve(nums, k):
    def find_kth_smallest(nums, k):
        heap = []
        for i, num in enumerate(nums):
            if i < k:
                heapq.heappush(heap, num)
            else:
                if num < heap[0]:
                    heapq.heappop(heap)
                    heapq.heappush(heap, num)
        return heap[0]

    return find_kth_smallest(nums, k)
