def solve(haystack, needle):
    len_h = len(haystack)
    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Preprocess the needle to create a list of character positions
    last_occurrence = {}
    for i, char in enumerate(needle):
        last_occurrence[char] = i

    # Initialize the search
    i = 0
    while i <= len_h - len_n:
        j = len_n - 1
        while j >= 0:
            if haystack[i + j] != needle[j]:
                # Shift i by the maximum possible amount
                if i + j + 1 < len_h and haystack[i + j + 1] in last_occurrence:
                    i += max(j + 1 - last_occurrence[haystack[i + j + 1]], 1)
                else:
                    i += j + 1
                break
            j -= 1
        else:
            return i
    return -1
```

