        return [
            [a[0]*b[0] + a[1]*b[2], a[0]*b[1] + a[1]*b[3]],
            [a[2]*b[0] + a[3]*b[2], a[2]*b[1] + a[3]*b[3]]
        ]

    def matrix_pow(matrix, power):
        result = [[1, 0], [0, 1]]  # Identity matrix
        while power > 0:
            if power % 2 == 1:
                result = matrix_mult(result, matrix)
            matrix = matrix_mult(matrix, matrix)
            power //= 2
        return result

