        return 0
    elif n == 1:
        return 1

    # Fibonacci matrix [[1, 1], [1, 0]] raised to (n-1)th power
    fib_matrix = [[1, 1], [1, 0]]
    powered = matrix_pow(fib_matrix, n - 1)
    return powered[0][0]
