            return [[1, 1], [1, 0]]
        else:
            mat = fib_matrix(n // 2)
            mat = matrix_mult(mat, mat)
            if n % 2 == 1:
                mat = matrix_mult(mat, [[1, 1], [1, 0]])
            return mat

