from collections import defaultdict

def solve(nums, k):
    frequency = defaultdict(int)
    for num in nums:
        frequency[num] += 1

    sorted_items = sorted(frequency.items(), key=lambda x: (-x[1], x[0]))

    result = []
    count = 0
    current_freq = None

    for num, freq in sorted_items:
        if current_freq is None:
            current_freq = freq
            count = 1
        elif freq == current_freq:
            count += 1
        else:
            if count >= k:
                result.extend([num for _ in range(k)])
            current_freq = freq
            count = 1

    if count >= k:
        result.extend([num for _ in range(k)])

    return result
