from collections import defaultdict

def solve(nums, k):
    count = defaultdict(int)
    for num in nums:
        count[num] += 1

    freq = list(count.items())
    freq.sort(key=lambda x: (-x[1], x[0]))

    result = []
    current_freq = freq[0][1]
    current_count = 1
    for i in range(1, len(freq)):
        if freq[i][1] == current_freq:
            current_count += 1
        else:
            if current_count == k:
                result.extend([x[0] for x in freq[:i]])
            current_freq = freq[i][1]
            current_count = 1
    if current_count == k:
        result.extend([x[0] for x in freq])

    return result
