def solve(nums):
    def count_increments(seq, target):
        left, right = 0, len(seq)
        while left < right:
            mid = (left + right) // 2
            if seq[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    dp = []
    for num in nums:
        idx = count_increments(dp, num)
        if idx == len(dp):
            dp.append(num)
        else:
            dp[idx] = num
    return len(dp)
